mapper.select:
SELECT id, userId, goodsId, addressId, preId, goodsName, `describe`, goodsPrice, goodsStock, imagePath, launch, createTime, `delete`
FROM goods

    AND id = #{entity.id}
    AND userId = #{entity.userId}
    AND goodsId = #{entity.goodsId}
    AND addressId = #{entity.addressId}
    AND preId = #{entity.preId}
    AND goodsName = #{entity.goodsName}
    AND `describe` = #{entity.describe}
    AND goodsPrice = #{entity.goodsPrice}
    AND goodsStock = #{entity.goodsStock}
    AND imagePath = #{entity.imagePath}
    AND launch = #{entity.launch}
    AND createTime = #{entity.createTime}
    AND `delete` = #{entity.delete}

SELECT g.id, g.userId, g.goodsId, g.addressId, g.goodsName, g.`describe`, g.goodsPrice, g.goodsStock, g.imagePath, g.launch, g.createTime, g.`delete`, u.userName, u.avatarPath AS merchantAvatar, u.id AS merchantId, CONCAT(ad.country, ad.province, ad.city, ad.county, ad.detail) AS address, CASE WHEN c.id IS NOT NULL THEN true ELSE false END AS inCart, CASE WHEN c.id IS NOT NULL THEN c.quantity ELSE 0 END AS cartQuantity FROM goods g LEFT JOIN user u ON g.userId = u.id LEFT JOIN address ad ON g.addressId = ad.id LEFT JOIN cart c ON c.goodId = g.id AND c.userId = #{userId} WHERE g.id IN
#{id}
AND g.launch = 1 AND g.`delete` = 0
